def next_smallest(lst):
    if len(lst) < 2:
        return None
    unique_elements = sorted(set(lst))
    return unique_elements[1] if len(unique_elements) > 1 else None

def valid_date(date):
    if len(date) != 10 or date[2] != '-' or date[5] != '-':
        return False
    month, day, year = map(int, date.split('-'))
    if month < 1 or month > 12:
        return False
